       updated_at      = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Udvasanam';

update public.pooja_steps set
       mantra_sanskrit = 'बालभानु प्रतीकाशं पूर्णचन्द्रनिभाननं।
सूत्रेऽस्मिन् सुस्थिता भूत्वा प्रयच्छ बहुलान् वरान्।।',
       mantra_tamil    = 'பாலபாநு ப்ரதீகாஶம் பூர்ணசந்த்ரநிபாநநம்।
ஸூத்ரேஸ்மிந் ஸுஸ்திதா பூத்வா ப்ரயச்ச பஹுலாந் வராந்।।',
