-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- Not one ASCII colon may remain in any script column, in any pooja.
  select count(*) into n from public.pooja_steps
   where mantra_sanskrit like '%:%' or mantra_tamil like '%:%'
      or mantra_translit like '%:%';
  if n > 0 then raise exception '% steps still carry an ASCII colon', n; end if;

  select count(*) into n from public.archana_items
   where invoked_name_deva like '%:%' or invoked_name_ta like '%:%'
      or invoked_name_translit like '%:%' or offering_deva like '%:%'
      or offering_ta like '%:%';
  if n > 0 then raise exception '% archana rows still carry an ASCII colon', n; end if;

  select count(*) into n from public.namavali_items
   where name_deva like '%:%' or name_ta like '%:%' or name_translit like '%:%';
  if n > 0 then raise exception '% namavali items carry an ASCII colon', n; end if;

  -- And the visarga is present in each script where it belongs.
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Anga Pooja'
     and a.invoked_name_ta like '%' || chr(42889) || '%';
  if n <> 24 then raise exception 'only % of 24 anga rows have the Tamil visarga', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
